('ad6db068-6f20-51de-84bc-09f0edc8d69d'::uuid,'EOC-F04','Incident briefing and shift handover','Chapter 4 EOC-F04 (SOP 4-05 steps 6-7; SOP 4-04 step 6).','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'{"fields": [{"key": "situation", "label": "Situation, source and time", "type": "textarea", "required": true}, {"key": "objectives", "label": "Objectives", "type": "textarea", "required": true}, {"key": "open_tasks", "label": "Open tasks, requests and decisions", "type": "textarea", "required": true}, {"key": "risks", "label": "Risks and constraints", "type": "textarea", "required": false}, {"key": "next_review", "label": "Next briefing or handover time", "type": "text", "required": true}]}'::jsonb,'draft',1),
('48b7ccf3-2c40-5d7a-a666-0fe6bfacb4ce'::uuid,'ER-F01','Evacuation coordination and monitoring sheet','Chapter 4 ER-F01 (SOP 4-06). Counts only; no names.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'{"fields": [{"key": "decision_ref", "label": "Authorised decision or order (reference)", "type": "text", "required": true, "hint": "Who decided under which issuance"}, {"key": "areas", "label": "Barangays or puroks covered", "type": "textarea", "required": true}, {"key": "families_moved", "label": "Families moved (aggregate)", "type": "integer", "required": false}, {"key": "persons_moved", "label": "Persons moved (aggregate)", "type": "integer", "required": false}, {"key": "centres_open", "label": "Evacuation centres open", "type": "integer", "required": false}, {"key": "transport_access", "label": "Transport and access issues", "type": "textarea", "required": false}, {"key": "unmet_needs", "label": "Unmet needs and the office handling each", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('9039d834-9eb5-5d60-b3ab-69bca67857ee'::uuid,'ER-F02','Response deployment and safety coordination record','Chapter 4 ER-F02.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'{"fields": [{"key": "requesting_authority", "label": "Requesting authority", "type": "text", "required": true}, {"key": "task", "label": "Task and location", "type": "textarea", "required": true}, {"key": "lead_agency", "label": "Lead agency", "type": "text", "required": true}, {"key": "check_in", "label": "Check-in time", "type": "time", "required": false}, {"key": "safety", "label": "Safety briefing and hazards noted", "type": "textarea", "required": true}, {"key": "status", "label": "Status", "type": "select", "required": true, "options": ["Deployed", "On task", "Completed", "Withdrawn"]}]}'::jsonb,'draft',1),
('80bc395f-2c27-5df9-bb05-d573c387803f'::uuid,'ER-F03','Shelter and CCCM service coordination summary','Chapter 4 ER-F03; JMC No. 2 s. 2021 (CCCM). Aggregates only; DAFAC stays with the CSWDO.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'{"fields": [{"key": "facility", "label": "Evacuation centre or site", "type": "text", "required": true}, {"key": "families", "label": "Families in the centre (aggregate)", "type": "integer", "required": false}, {"key": "persons", "label": "Persons in the centre (aggregate)", "type": "integer", "required": false}, {"key": "services", "label": "Services in place", "type": "multiselect", "required": false, "options": ["Camp manager assigned", "Registration (DAFAC) by CSWDO", "Food and NFI", "WASH", "Health", "Protection and child-friendly space", "Women-friendly space", "Accessibility for PWD and older persons", "Security"]}, {"key": "issues", "label": "Issues and referrals (no names)", "type": "textarea", "required": false}, {"key": "closure", "label": "Closure or decampment status", "type": "text", "required": false}]}'::jsonb,'draft',1),
('71026fb5-4ffa-56ed-9100-b30bcfbb6313'::uuid,'ER-F04','Public information verification and correction log','Chapter 4 ER-F04 (sec. 10.5).','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'{"fields": [{"key": "claim", "label": "Claim or rumour", "type": "textarea", "required": true}, {"key": "source", "label": "Where it was seen", "type": "text", "required": true}, {"key": "verification", "label": "Verification status", "type": "select", "required": true, "options": ["Unverified", "Verified true", "Verified false", "Partly true"]}, {"key": "approved_message", "label": "Approved message issued", "type": "textarea", "required": false}, {"key": "feedback", "label": "Feedback received", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('6bbee571-3959-54b0-aeb2-446986e37c90'::uuid,'EOC-F06','Resource request referral and status sheet','Chapter 4 EOC-F06 (SOP 4-07). Expenditure follows Chapter 5.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'{"fields": [{"key": "request_ref", "label": "Resource request reference", "type": "text", "required": true}, {"key": "priority", "label": "Priority", "type": "select", "required": true, "options": ["Life-safety", "Urgent", "Routine"]}, {"key": "owner", "label": "Asset owner or office", "type": "text", "required": true}, {"key": "approval_route", "label": "Approval route and decision", "type": "textarea", "required": true}, {"key": "dispatch", "label": "Dispatch, receipt and custody", "type": "textarea", "required": false}, {"key": "closeout", "label": "Closeout: used, returned, outstanding", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('9e125c8c-0bec-5c3d-b8c1-8d0443b7abc2'::uuid,'ER-F05','Demobilisation and transition handover register entry','Chapter 4 ER-F05 (SOP 4-09 step 4).','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'{"fields": [{"key": "item", "label": "Outstanding task, resource or information", "type": "textarea", "required": true}, {"key": "receiving_office", "label": "Receiving office", "type": "text", "required": true}, {"key": "due", "label": "Due date", "type": "date", "required": true}, {"key": "acknowledged", "label": "Receipt acknowledged by the receiving office", "type": "checkbox", "required": true}]}'::jsonb,'draft',1),
